<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class Product extends Model { protected $fillable=['category_id','name','slug','sku','brand','description','price','compare_at_price','stock','image','images','specifications','is_active','is_featured']; protected $casts=['price'=>'decimal:2','compare_at_price'=>'decimal:2','images'=>'array','specifications'=>'array','is_active'=>'boolean','is_featured'=>'boolean']; public function category(){return $this->belongsTo(Category::class);} public function scopeActive($q){return $q->where('is_active',true);} }